{
  "name": "opencode-user-timeline",
  "version": "0.2.4",
  "description": "OpenCode 2 TUI 插件：在会话侧边栏显示用户消息时间线，支持滚轮浏览与点击跳转定位。Sidebar timeline of your messages with scroll & click-to-jump.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "https://github.com/huahai0202/opencode-user-timeline.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode2",
    "tui"
  ],
  "engines": {
    "opencode": ">=2.0.2"
  },
  "exports": {
    ".": "./dist/index.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "babel src --out-dir dist --extensions .ts,.tsx",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/client": "^2.0.0",
    "@opencode/plugin": "^2.0.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17 <0.6.0",
    "@opentui/solid": ">=0.5.17 <0.6.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@babel/cli": "^7.29.7",
    "@babel/core": "^7.29.7",
    "@babel/preset-typescript": "^7.27.1",
    "@opentui/core": "^0.5.17",
    "@opentui/solid": "^0.5.17",
    "@types/node": "^26.0.1",
    "babel-preset-solid": "1.9.12",
    "solid-js": "1.9.12",
    "typescript": "^6.0.3"
  }
}
